package com.orderflow.notification.security;import org.springframework.context.annotation.*;import org.springframework.core.convert.converter.Converter;import org.springframework.security.authentication.AbstractAuthenticationToken;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.oauth2.server.resource.web.authentication.BearerTokenAuthenticationFilter;import org.springframework.security.web.SecurityFilterChain;@Configuration public class NotificationSecurityConfiguration{@Bean SecurityFilterChain notificationSecurityFilterChain(HttpSecurity h,RestAuthenticationEntryPoint e,RestAccessDeniedHandler d,RevocationValidationFilter r,Converter<Jwt,AbstractAuthenticationToken>c)throws Exception{return h.sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).csrf(x->x.disable()).formLogin(x->x.disable()).httpBasic(x->x.disable()).logout(x->x.disable()).authorizeHttpRequests(a->a.requestMatchers(org.springframework.http.HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/actuator/health/**","/actuator/info","/actuator/prometheus").permitAll().requestMatchers("/api/notifications/**").authenticated().anyRequest().authenticated()).exceptionHandling(x->x.authenticationEntryPoint(e).accessDeniedHandler(d)).oauth2ResourceServer(x->x.jwt(j->j.jwtAuthenticationConverter(c)).authenticationEntryPoint(e).accessDeniedHandler(d)).addFilterAfter(r,BearerTokenAuthenticationFilter.class).build();}}
